from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund, APPROVAL_THRESHOLD
from ledgerly.models import Payment
from ledgerly.errors import BillingError

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(amt="2000.00", status="captured"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# at threshold no approval
p=mk(); outage_refund(p, Decimal("1000.00"), T0); print("at threshold ok", p.refunded_amount)
# above threshold requires approval
p=mk()
try: outage_refund(p, Decimal("1000.01"), T0)
except BillingError as e: print("approval required:", e.code)
# with approval
p=mk(); outage_refund(p, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok", p.refunded_amount)
# keyword-only
try: outage_refund(mk(), Decimal("1.00"), T0, "mgr")
except TypeError as e: print("keyword-only enforced")
# over refund
p=mk("10.00")
try: outage_refund(p, Decimal("11.00"), T0)
except BillingError as e: print("over:", e.code)
# non-captured
try: outage_refund(mk(status="authorized"), Decimal("1.00"), T0)
except BillingError as e: print("state:", e.code)
# full refund sets status
p=mk("10.00"); outage_refund(p, Decimal("10.00"), T0); print("status:", p.status)
# non-positive
try: outage_refund(mk(), Decimal("0"), T0)
except BillingError as e: print("nonpositive:", e.code)
EOF"}

